theorem MIPRE.Introspection.CLChecks.outputPrefix_outputPrefix {P : CL.CLFun F ι ℓ} {T : Finset ι}
    (hP : P.SupportedOn T) (y : ι → F) {k m : ℕ} (hkm : k ≤ m) :
    P.outputPrefix k (P.outputPrefix m y) = P.outputPrefix k y := by sorry

theorem MIPRE.Introspection.CLChecks.dualReadout_congr {P : CL.CLFun F ι ℓ} {T : Finset ι}
    (hP : P.SupportedOn T) (k : ℕ) (y : ι → F) {x t : ι → F}
    (h : ∀ i ∈ T, x i = t i) : dualReadout P k y x = dualReadout P k y t := by sorry

theorem MIPRE.Introspection.CLChecks.proj_outputPrefix_cons {S T : Finset ι} {L : CL.RegLinear F S}
    {next : (ι → F) → CL.CLFun F ι ℓ}
    (hP : (CL.CLFun.cons S L next).SupportedOn T) (k : ℕ) (y : ι → F) :
    CL.proj S ((CL.CLFun.cons S L next).outputPrefix (k + 1) y) = CL.proj S y ∧
    CL.proj Sᶜ ((CL.CLFun.cons S L next).outputPrefix (k + 1) y) =
      (next (CL.proj S y)).outputPrefix k (CL.proj Sᶜ y) := by sorry
